export const getArticle = (slug) => ARTICLES.find((a) => a.slug === slug) || null

export const CAT_LABEL = { bourse: 'Bourse', crypto: 'Crypto', epargne: 'Épargne' }

export const dateFr = (iso) =>
  new Date(iso + 'T12:00:00').toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' }).replace(/^1 /, '1er ')
